package fr.iut.laGaule;

import fr.iut.laGaule.model.Character.ClanLeader;
import fr.iut.laGaule.model.Character.Character;
import fr.iut.laGaule.model.Character.Gaul.Druid;
import fr.iut.laGaule.model.Character.Gaul.Innkeeper;
import fr.iut.laGaule.model.Character.Gaul.Merchant;
import fr.iut.laGaule.model.Character.Roman.General;
import fr.iut.laGaule.model.Character.Roman.Legionary;
import fr.iut.laGaule.model.Consumables.Foods.Foods;
import fr.iut.laGaule.model.Place.*;

import java.util.ArrayList;

/**
 * Classe d'exemple démontrant l'utilisation de ClanLeader
 */
public class ExempleClanLeader {
    public static void main(String[] args) {
        System.out.println("=== EXEMPLE D'UTILISATION DE CLAN LEADER ===\n");

        // Création d'un village gaulois avec quelques personnages et aliments
        ArrayList<Character> gauloisPersonnages = new ArrayList<>();
        ArrayList<Foods> gauloisAliments = new ArrayList<>();

        gauloisAliments.add(Foods.SANGLIER);
        gauloisAliments.add(Foods.POISSON_FRAIS);
        gauloisAliments.add(Foods.VIN);
        gauloisAliments.add(Foods.MIEL);

        // Création d'un chef de clan gaulois
        ClanLeader abraracourcix = new ClanLeader("Abraracourcix", "male", 45);

        GaulVillage village = new GaulVillage(
            "Village d'Astérix",
            5000,
            abraracourcix,
            0,
            gauloisPersonnages,
            gauloisAliments
        );

        // Assigner le village au chef de clan
        abraracourcix.setManagedPlace(village);

        System.out.println(abraracourcix.toString());

        // 1. Examiner le lieu
        System.out.println("\n--- 1. Le chef examine son village ---");
        abraracourcix.examineManagedPlace();

        // 2. Créer de nouveaux personnages
        System.out.println("\n--- 2. Le chef crée de nouveaux personnages ---");
        Character asterix = abraracourcix.createCharacter("druid", "Panoramix", "male", 1.65, 60, 40, 50);
        Character obelix = abraracourcix.createCharacter("merchant", "Obélix", "male", 1.85, 35, 95, 85);
        Character assurancetourix = abraracourcix.createCharacter("innkeeper", "Assurancetourix", "male", 1.70, 30, 50, 45);

        // 3. Examiner le lieu après création
        System.out.println("\n--- 3. Examen après création de personnages ---");
        abraracourcix.examineManagedPlace();

        // 4. Nourrir un personnage spécifique
        System.out.println("\n--- 4. Le chef nourrit Obélix ---");
        abraracourcix.feedCharacter(obelix);

        // 5. Demander à un druide de faire la potion
        System.out.println("\n--- 5. Le chef demande au druide de préparer la potion ---");
        if (asterix instanceof Druid) {
            abraracourcix.askDruidForMagicPotion((Druid) asterix);
        }

        // 6. Faire boire la potion à un personnage
        System.out.println("\n--- 6. Le chef donne la potion à Obélix ---");
        abraracourcix.giveMagicPotion(obelix, 50);

        // 7. Soigner un personnage blessé
        System.out.println("\n--- 7. Simulation d'un combat et soins ---");
        obelix.receiveDamage(30);
        abraracourcix.healCharacter(obelix, 20);

        // 8. Créer un champ de bataille et y transférer un personnage
        System.out.println("\n--- 8. Transfert vers un champ de bataille ---");
        ArrayList<Character> combattants = new ArrayList<>();
        ArrayList<Foods> provisionsCombat = new ArrayList<>();

        BattleFields battlefield = new BattleFields(
            "Plaine de Gergovie",
            10000,
            null,
            0,
            combattants,
            provisionsCombat
        );

        abraracourcix.transferToBattleField(obelix, battlefield);

        // 9. Créer un enclos
        System.out.println("\n--- 9. Transfert vers un enclos ---");
        ArrayList<Character> prisonniersEnclos = new ArrayList<>();
        ArrayList<Foods> alimentsEnclos = new ArrayList<>();

        Enclosure enclos = new Enclosure(
            "Enclos du village",
            500,
            null,
            0,
            prisonniersEnclos,
            alimentsEnclos
        );

        // Créer un romain à enfermer
        Character centurion = abraracourcix.createCharacter("legionary", "Caius Bonus", "male", 1.75, 35, 60, 55);
        abraracourcix.transferToEnclosure(centurion, enclos);

        // 10. Examen final
        System.out.println("\n--- 10. État final du village ---");
        abraracourcix.examineManagedPlace();

        System.out.println("\n--- État du champ de bataille ---");
        System.out.println(battlefield.toString());

        System.out.println("\n--- État de l'enclos ---");
        System.out.println(enclos.toString());

        // Exemple avec un camp romain
        System.out.println("\n\n=== EXEMPLE AVEC UN CAMP ROMAIN ===\n");

        ArrayList<Character> romainsPersonnages = new ArrayList<>();
        ArrayList<Foods> romainsAliments = new ArrayList<>();

        romainsAliments.add(Foods.SANGLIER);
        romainsAliments.add(Foods.MIEL);
        romainsAliments.add(Foods.HYDROMEL);

        ClanLeader centurionEnChef = new ClanLeader("Centurion Marcus", "male", 40);

        RomanFortifiedCamp camp = new RomanFortifiedCamp(
            "Camp Babaorum",
            8000,
            centurionEnChef,
            0,
            romainsPersonnages,
            romainsAliments
        );

        centurionEnChef.setManagedPlace(camp);

        System.out.println(centurionEnChef.toString());

        // Créer des légionnaires
        centurionEnChef.createCharacter("legionary", "Légionnaire 1", "male", 1.80, 25, 55, 50);
        centurionEnChef.createCharacter("legionary", "Légionnaire 2", "male", 1.75, 28, 58, 52);
        centurionEnChef.createCharacter("general", "Général Tullius", "male", 1.78, 45, 70, 65);

        centurionEnChef.examineManagedPlace();

        // Nourrir tous les personnages
        System.out.println("\n--- Le centurion nourrit tous ses hommes ---");
        centurionEnChef.feedAllCharacters();

        System.out.println("\n=== FIN DE L'EXEMPLE ===");
    }
}
